import torch
from collections import deque
import hashlib
import torch.nn as nn

def find_start_end(maze):
    start = tuple(position for position in zip(*torch.where(maze == 2)))
    end = tuple(position for position in zip(*torch.where(maze == 3)))
    return start[0], end[0]

def is_valid_move(maze, pos):
    rows, cols = maze.shape
    return (0 <= pos[0] < rows and 
            0 <= pos[1] < cols and 
            maze[pos] != 1)  # Not a wall

def bfs_shortest_path(maze):
    start, end = find_start_end(maze)
    queue = deque([(start, [])])
    visited = {start}

    # Possible moves: up, right, down, left
    moves = [(-1, 0), (0, 1), (1, 0), (0, -1)]
    directions = ['W', 'D', 'S', 'A']

    while queue:
        current, path = queue.popleft()

        if current == end:
            return ''.join(path)

        for i, (dy, dx) in enumerate(moves):
            next_pos = (current[0] + dy, current[1] + dx)

            if next_pos not in visited and is_valid_move(maze, next_pos):
                queue.append((next_pos, path + [directions[i]]))
                visited.add(next_pos)

    return None  # No path found

# Load maze directly as tensor
maze = torch.load('/home/ctfplayer/ctf_files/attachment/maze.pt')
if isinstance(maze, nn.Module):
    # Try to get the maze data from various attributes
    if hasattr(maze, 'weight'):
        maze = maze.weight
    elif hasattr(maze, 'data'):
        maze = maze.data
    elif hasattr(maze, '_parameters'):
        maze = next(iter(maze._parameters.values()))

print("Maze shape:", maze.shape)

# Print maze for visualization
print("\nMaze:")
for row in maze:
    print(''.join(str(int(x.item())) for x in row))

path = bfs_shortest_path(maze)
print(f"\nShortest path: {path}")

# Calculate flag (MD5 hash wrapped in flag{})
if path:
    flag_hash = hashlib.md5(path.encode()).hexdigest()
    flag = f"flag{{{flag_hash}}}"
    print(f"Flag: {flag}")

